<script>function bindImagePreview(selectId,fileId,previewId){const preview=document.getElementById(previewId);const show=src=>{preview.src=src;preview.classList.toggle('hidden',!src)};document.getElementById(selectId).addEventListener('change',event=>show(event.target.selectedOptions[0]?.dataset.preview||''));document.getElementById(fileId).addEventListener('change',event=>show(event.target.files[0]?URL.createObjectURL(event.target.files[0]):''))}bindImagePreview('site-logo-select','site-logo-file','site-logo-preview');bindImagePreview('header-image-select','header-image-file','header-image-preview');</script></main></x-layouts::app>
